DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_1','The Republic of First Drafts[NEWLINE]Institutional variety and permanent first-possession rewards[NEWLINE]Science or Culture[NEWLINE][NEWLINE]Build or acquire useful new ordinary Building Classes across the empire, then develop diversified Workshop cities. National first recognition and current local building diversity are separate systems and should guide different decisions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_2','Choose affordable institutions that solve real needs while broadening the empire''s recognized classes. Do not buy an irrelevant building just because its reward exists; compare its full cost with what the city requires.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_3','Use purchases, faith buildings and acquisitions where they make economic sense. Add Revision Workshops to cities with enough qualifying local diversity to support their Science thresholds. Repeat buildings still help those cities even after the empire''s first reward is consumed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_4','Use the permanent Culture/Gold gains and diversified research cities for a conventional victory. Keep military support for Ink Mortars; extra movement and sight do not remove ordinary siege setup or attack restrictions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_5','- Several legitimate possession routes can establish a new ordinary class.[NEWLINE]- National recognition remains earned after later building loss.[NEWLINE]- Local Workshop Science rewards developed institutional variety.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_6','- Each qualifying class pays only once per game across the empire.[NEWLINE]- Wonders and hidden or invalid control buildings do not qualify.[NEWLINE]- Workshop Science depends on current local diversity and has a cap.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_7','- Pressure developing cities before their varied infrastructure becomes a durable economy.[NEWLINE]- Contest the ordinary research and cultural race rather than expecting repeated class copies to fuel endless rewards.[NEWLINE]- Use mobility and range to punish an unsupported siege unit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_8','- Expecting a second city to repeat the same national class reward.[NEWLINE]- Counting Wonders or every hidden building toward eligibility.[NEWLINE]- Assuming a lost building erases the national reward or that the local Workshop count is permanent.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: Useful cheap institutional variety can create earlier tempo while Sol commits to longer uninterrupted construction.[NEWLINE][NEWLINE]Saba: On poor River/Desert terrain, institutional development has more routes than Saba''s site-specific additions.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Shattered Empire: An organized initial imperial footprint can contest sites and safety before Marginalia''s institutional base is mature.[NEWLINE][NEWLINE]McPvP: Infiltration and objective pressure can divert a builder economy into emergency defense and delay additional institutions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_DESCRIPTION','The Republic of First Drafts');
