INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_BACKGROUND','Build or acquire useful new ordinary Building Classes across the empire, then develop diversified Workshop cities. National first recognition and current local building diversity are separate systems and should guide different decisions.');
