INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_STRATEGY','Build or acquire useful new ordinary Building Classes across the empire, then develop diversified Workshop cities. National first recognition and current local building diversity are separate systems and should guide different decisions.[NEWLINE][NEWLINE]Choose affordable institutions that solve real needs while broadening the empire''s recognized classes. Do not buy an irrelevant building just because its reward exists; compare its full cost with what the city requires.[NEWLINE][NEWLINE]Use purchases, faith buildings and acquisitions where they make economic sense. Add Revision Workshops to cities with enough qualifying local diversity to support their Science thresholds. Repeat buildings still help those cities even after the empire''s first reward is consumed.[NEWLINE][NEWLINE]Use the permanent Culture/Gold gains and diversified research cities for a conventional victory. Keep military support for Ink Mortars; extra movement and sight do not remove ordinary siege setup or attack restrictions.');
