INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_LEADER_TEXT_2','Choose affordable institutions that solve real needs while broadening the empire''s recognized classes. Do not buy an irrelevant building just because its reward exists; compare its full cost with what the city requires.[NEWLINE][NEWLINE]Use purchases, faith buildings and acquisitions where they make economic sense. Add Revision Workshops to cities with enough qualifying local diversity to support their Science thresholds. Repeat buildings still help those cities even after the empire''s first reward is consumed.[NEWLINE][NEWLINE]Use the permanent Culture/Gold gains and diversified research cities for a conventional victory. Keep military support for Ink Mortars; extra movement and sight do not remove ordinary siege setup or attack restrictions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THEREPUBLICOFFIRSTDRAFTS_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: Useful cheap institutional variety can create earlier tempo while Sol commits to longer uninterrupted construction.[NEWLINE][NEWLINE]Saba: On poor River/Desert terrain, institutional development has more routes than Saba''s site-specific additions.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Shattered Empire: An organized initial imperial footprint can contest sites and safety before Marginalia''s institutional base is mature.[NEWLINE][NEWLINE]McPvP: Infiltration and objective pressure can divert a builder economy into emergency defense and delay additional institutions.');
